<template>
 <a-card :bordered="false">
  <h2>订单全过程进度看板</h2><p>查看范围：{{options.scope}}。看板只查询；点击进度进入对应订单或任务，办理权限沿用原模块。</p>
  <a-form layout="inline"><a-form-item label="订单 / 客户"><a-input v-model="keyword" @pressEnter="load()"/></a-form-item><a-button type="primary" @click="load()">查询</a-button><a-button @click="keyword='';load()" style="margin-left:8px">重置</a-button></a-form>
  <a-table style="margin-top:16px" :columns="columns" :data-source="rows" row-key="head_id" :pagination="pagination" :loading="loading" @change="onPage"><template slot="state" slot-scope="v">{{orderStates[v]}}</template><template slot="production" slot-scope="v">{{productionStates[v]||'未建立任务'}}</template><template slot="shipping" slot-scope="v">{{shippingStates[v]||'未申请'}}</template><a slot="action" slot-scope="_,r" @click="open(r.head_id)">查看全流程进度</a></a-table>
  <j-modal title="订单全过程进度" :visible="visible" :width="1300" :footer="null" @cancel="visible=false">
   <div class="heading"><div><h2>{{detail.number}}　{{detail.customer_name}}</h2><p>{{orderStates[detail.workflow_status]}}　交期：{{String(detail.delivery_date||'').slice(0,10)}}　付款条件：{{terms[detail.payment_terms]}}</p></div><a-button :loading="refreshing" @click="open(detail.head_id)">刷新最新进度</a-button></div>
   <p>客户要求：{{detail.requirements||'—'}}</p><p v-if="detail.total_price!=null">订单含税金额：{{detail.total_price}} 元</p>
   <a-alert type="info" show-icon :message="detail.scope+'。数量单位：吨。末工序产出单独统计，不累加各工序产出；整批入库、放行数量为历史批次数量，不代表当前库存。'"/>
   <h3>环节进度 · 点击进入对应模块</h3><div class="steps-grid"><div v-for="l in detail.links" :key="l.url" class="progress-card" :class="{available:l.enabled}" :role="l.enabled?'button':undefined" :tabindex="l.enabled?0:undefined" @click="jump(l)" @keydown.enter.prevent="jump(l)"><h4>{{l.title}}</h4><p>{{progressText(l.url)}}</p><span>{{l.enabled?'查看 / 进入办理 →':'仅查看进度，暂无对应入口权限或不适用'}}</span></div></div>
   <h3>当前待处理事项</h3><ul v-if="detail.pending.length"><li v-for="(p,i) in detail.pending" :key="i">{{p}}</li></ul><p v-else>本范围暂无已记录的待处理事项，可按上方各环节继续核对。</p>
   <h3>产品需求与末工序产出</h3><div class="scroll"><table class="progress-table"><thead><tr><th>产品 / 条码</th><th>需求量</th><th>已预留</th><th>最后工序</th><th>本查看范围末工序产出</th><th v-if="detail.total_price!=null">原含税单价</th></tr></thead><tbody><tr v-for="p in detail.lines" :key="p.lineNo"><td>{{p.name}} / {{p.barCode}}<br>{{p.brand}} {{p.standard}} {{p.model}}</td><td>{{p.quantity}}</td><td>{{p.reserved}}</td><td>{{p.finalStage||'未安排'}}</td><td>{{p.finalOutput}}</td><td v-if="detail.total_price!=null">{{p.price}}</td></tr></tbody></table></div>
   <h3>各产品、工序、车间实际进度</h3><div class="scroll"><table class="progress-table"><thead><tr><th>产品</th><th>工序</th><th>车间</th><th>累计计划</th><th>实际开工</th><th>投入</th><th>产出</th><th>损耗</th></tr></thead><tbody><tr v-for="(r,i) in detail.stages" :key="i"><td>{{lineName(r.lineNo)}}</td><td>{{r.stageNo}}</td><td>{{r.workshopNo}}</td><td>{{r.planned}}</td><td>{{r.actualStart?String(r.actualStart).replace('T',' '):'未开工'}}</td><td>{{r.input}}</td><td>{{r.output}}</td><td>{{r.loss}}</td></tr></tbody></table></div>
   <h3>检测与工序交接</h3><div class="scroll"><table class="progress-table"><thead><tr><th>送检单</th><th>产品 / 工序 / 车间</th><th>批号</th><th>类型</th><th>代表数量</th><th>确认合格量</th><th>状态</th></tr></thead><tbody><tr v-for="r in detail.inspections" :key="r.id"><td><a v-if="can(qualityUrl(r))" @click="go(qualityUrl(r),{taskId:detail.head_id,inspectionId:r.id})">ZJ{{r.id}}</a><span v-else>ZJ{{r.id}}</span></td><td>{{lineName(r.line_no)}} / {{r.stage_no}} / {{r.workshop_no}}</td><td>{{r.batch_number}}</td><td>{{r.inspection_kind==='finished'?'成品':'半成品'}}{{r.parent_id?'（复检）':''}}</td><td>{{r.quantity}}</td><td>{{r.qualified_quantity==null?'—':r.qualified_quantity}}</td><td>{{qcStates[r.workflow_status]}}</td></tr></tbody></table></div>
   <p v-for="r in detail.transfers" :key="'transfer'+r.id">交接#{{r.id}}：{{lineName(r.line_no)}} / {{r.batch_number}} / 车间{{r.source_workshop}} → 工序{{r.stage_no}}车间{{r.workshop_no}} / {{r.quantity}} 吨 / {{r.workflow_status==='received'?'已接收':'待接收车间确认'}}</p>
   <h3>成品整批质检、入库与放行</h3><div class="scroll"><table class="progress-table"><thead><tr><th>产品 / 批号</th><th>整批数量</th><th>仓库</th><th>当前进度</th></tr></thead><tbody><tr v-for="r in detail.batches" :key="r.id"><td>{{lineName(r.line_no)}} / {{r.batch_number}}</td><td>{{r.quantity}}</td><td>{{r.depot_name||'尚未入库'}}</td><td><a v-if="can('/factory/finished_product')" @click="go('/factory/finished_product',{taskId:detail.head_id})">{{r.progress}} →</a><span v-else>{{r.progress}}</span></td></tr></tbody></table></div>
   <h3>领补退料</h3><p v-if="!detail.materials.length">暂无领补退料单据。</p><p v-for="m in detail.materials" :key="m.id"><a v-if="can('/factory/material_request')" @click="go('/factory/material_request',{taskId:detail.head_id})">{{m.number}}</a><span v-else>{{m.number}}</span>　{{materialKinds[m.kind]}} / 工序{{m.stage_no}}车间{{m.workshop_no}} / {{materialStates[m.workflow_status]}}</p>
   <h3>收款与发货</h3><p v-if="detail.shipment">{{shippingStates[detail.shipment.workflow_status]}}　登记车辆：{{detail.shipment.truckCount}}　{{detail.payment_terms==='prepay'?(detail.shipment.paid?'财务已确认到账':'待财务确认到账'):'按账期条件发货'}}　出库时间：{{detail.shipment.shipped_at||'尚未出库'}}</p><p v-else>尚未申请发货；需核查整单预留及批次放行。</p>
   <h3>订单变更与取消</h3><p v-if="!detail.changes.length">暂无变更申请。</p><p v-for="c in detail.changes" :key="c.id"><a v-if="can('/factory/order_change')" @click="go('/factory/order_change',{changeId:c.id})">BG{{c.id}}</a><span v-else>BG{{c.id}}</span>　{{c.kind==='cancel'?'整单取消':'订单变更'}} / {{changeStates[c.workflow_status]}} / {{c.created_at}}</p>
   <h3>客户退货</h3><p v-if="!detail.returns.length">暂无退货申请。</p><p v-for="(r,i) in detail.returns" :key="i"><a v-if="can('/factory/returns')" @click="go('/factory/returns',{returnId:r.id})">TH{{r.id}}</a><span v-else>TH{{r.id}}</span>　{{r.quantity}} 吨 / {{returnStates[r.workflow_status]}} / {{r.received_at||r.created_at}}</p>
  </j-modal>
 </a-card>
</template>
<script>
import {getAction} from '@/api/manage'
const empty=()=>({lines:[],stages:[],inspections:[],transfers:[],batches:[],materials:[],changes:[],returns:[],links:[],pending:[]})
export default {
 name:'OrderProgressList',
 data(){return {options:{scope:''},keyword:'',rows:[],loading:false,refreshing:false,visible:false,detail:empty(),pagination:{current:1,pageSize:10,total:0},columns:[{title:'订单',dataIndex:'number'},{title:'客户',dataIndex:'customer_name'},{title:'交期',dataIndex:'delivery_date',customRender:v=>String(v||'').slice(0,10)},{title:'订单状态',dataIndex:'workflow_status',scopedSlots:{customRender:'state'}},{title:'生产安排',dataIndex:'production_state',scopedSlots:{customRender:'production'}},{title:'发货',dataIndex:'shipping_state',scopedSlots:{customRender:'shipping'}},{title:'操作',key:'action',scopedSlots:{customRender:'action'}}],orderStates:{draft:'草稿',pending:'待审核',returned:'已退回',approved:'审核通过',cancelled:'已取消'},productionStates:{draft:'联系表草稿',pending:'联系表待审核',returned:'联系表已退回',approved:'待统筹分配',distributed:'车间接单排班中',scheduled:'各车间已排班',cancelled:'联系表已撤销'},shippingStates:{requested:'已申请，待统一出库',shipped:'整单已出库',cancelled:'发货申请已撤销'},terms:{prepay:'款到发货',credit:'账期',unconfirmed:'待销售确认'},qcStates:{testing:'待开始检测',detecting:'检测中',returned:'退回补充检测',pending:'待质检主任确认',approved:'主任已确认'},materialKinds:{issue:'领料',supplement:'补料',return:'退料'},materialStates:{draft:'草稿',pending:'待仓库确认',returned:'已退回',confirmed:'仓库已确认',cancelled:'已撤销'},changeStates:{pending:'待领导审批，原计划继续',approved:'待统筹落实',applied:'已落实',rejected:'已退回',withdrawn:'已撤回'},returnStates:{pending:'待领导审批',approved:'待仓库收货',received:'已收货并恢复可销售',cancelled:'已撤销',rejected:'已退回'}}},
 created(){this.initialize()},watch:{'$route.query.orderId'(id){if(id)this.open(id)}},
 methods:{
  async api(path){const r=await getAction('/factoryProgress'+path);if(r.code!==200)throw new Error(r.message||(r.data&&r.data.message)||'查询失败');return r.data},
  error(e){this.$message.error(e.message||'查询失败')},
  async initialize(){try{this.options=await this.api('/options');await this.load();if(this.$route.query.orderId)await this.open(this.$route.query.orderId)}catch(e){this.error(e)}},
  async load(reset=true){if(reset)this.pagination.current=1;this.loading=true;try{const r=await this.api('/list?keyword='+encodeURIComponent(this.keyword)+'&page='+this.pagination.current);this.rows=r.rows;this.pagination.total=r.total}catch(e){this.error(e)}finally{this.loading=false}},
  onPage(p){this.pagination.current=p.current;this.load(false)},
  async open(id){this.refreshing=true;try{this.detail=await this.api('/'+id);this.visible=true}catch(e){this.error(e)}finally{this.refreshing=false}},
  can(url){return this.detail.links.some(l=>l.url===url&&l.enabled)},
  jump(l){if(l.enabled)this.go(l.url,l.query)},
  go(url,query){if(!this.can(url))return;this.visible=false;this.$router.push({path:url,query:Object.fromEntries(Object.entries(query).map(([k,v])=>[k,String(v)]))})},
  lineName(no){const p=this.detail.lines.find(l=>l.lineNo===no);return p?p.name:'产品'+(Number(no)+1)},
  qualityUrl(r){return r.inspection_kind==='finished'?'/factory/finished_product':'/factory/quality_transfer'},
  progressText(url){const d=this.detail;if(url==='/bill/sale_order')return this.orderStates[d.workflow_status];if(url==='/factory/stock_check')return d.workflow_status==='cancelled'?'已取消，预留已释放':d.lines.filter(l=>Number(l.reserved)>=Number(l.quantity)).length+' / '+d.lines.length+' 行已全量预留，批次放行仍需核对';if(url==='/factory/production_task')return d.production?this.productionStates[d.production.workflow_status]:'尚未建立任务，按库存缺口决定是否生产';if(url==='/factory/production_execution')return d.stages.length+' 组产品工序车间，查看实际投入、产出及损耗';if(url==='/factory/material_request')return d.materials.filter(m=>m.workflow_status==='pending').length+' 张待仓库确认';if(url==='/factory/quality_transfer')return d.inspections.filter(i=>i.inspection_kind!=='finished'&&i.workflow_status!=='approved').length+' 张待处理检测，'+d.transfers.filter(t=>t.workflow_status!=='received').length+' 笔待接收';if(url==='/factory/finished_product')return d.batches.length?d.batches.map(b=>b.batch_number+'：'+b.progress).join('；'):'暂无最终送检批次';if(url==='/factory/shipping')return d.shipment?this.shippingStates[d.shipment.workflow_status]:'尚未申请，需整单备齐并核对付款条件';if(url==='/factory/returns')return d.returns.length+' 条退货产品记录';if(url==='/factory/order_change')return d.changes.length?this.changeStates[d.changes[0].workflow_status]:'暂无变更申请';return ''}
 }
}
</script>
<style scoped>.heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.steps-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.progress-card{padding:16px;border:1px solid #ddd;border-radius:6px;background:#fafafa}.progress-card.available{cursor:pointer;background:#f0f8ff;border-color:#91caff}.progress-card.available:focus,.progress-card.available:hover{outline:2px solid #1890ff}.progress-card h4{font-size:16px}.progress-card p{margin:8px 0;overflow-wrap:anywhere}.progress-card span{font-size:12px;color:#666}.scroll{overflow-x:auto}.progress-table{width:100%;border-collapse:collapse;margin:12px 0}.progress-table td,.progress-table th{border:1px solid #ddd;padding:8px;text-align:left}h3{margin-top:24px}</style>
